code.source:
#include <iostream>
#include <string>
using namespace std;

class Book {
    string title_;
    int pages_;

public:
    Book(string title, int pages) : title_(title), pages_(pages) {
        cout << "Book made" << endl;
    }
    void show() const { cout << title_ << " " << pages_ << endl; }
};

int main() {
    Book b("Goa Tales", 120);
    b.show();
    return 0;
}

#include <iostream>
using namespace std;

class Ticket {
    const int id_;
    int price_;

public:
    Ticket(int id, int price) : id_(id), price_(price) {}
    void show() const { cout << id_ << " " << price_ << endl; }
};

int main() {
    Ticket t(101, 50);
    t.show();
    return 0;
}

